    render(`${topbar('İstatistiklerim','home')}<section class="statistics-hero"><div class="eyebrow">BUGÜNÜN ÖĞRENME ÖZETİ</div><h1>${today.answered?`${today.answered} soruyla zihnini çalıştırdın`:'Bugünkü yolculuk henüz başlamadı'}</h1><p>Doğru cevaplarının <b>%${recall}</b> kadarını şıklara bakmadan hafızandan çağırdın.</p><div class="recall-meter"><i style="width:${recall}%"></i></div></section><section class="statistics-grid">${cards.map(([label,value])=>`<article><span>${label}</span><strong>${value}</strong></article>`).join('')}</section><section class="statistics-insights"><article><span>En çok çalışılan</span><strong>${mostStudied?categoryNames[mostStudied[0]]||mostStudied[0]:'—'}</strong><small>${mostStudied?`${mostStudied[1].answered} soru`:'Henüz veri yok'}</small></article><article><span>En çok zorlanılan</span><strong>${mostDifficult?categoryNames[mostDifficult[0]]||mostDifficult[0]:'—'}</strong><small>${mostDifficult?`${mostDifficult[1].wrong} yanlış`:'Henüz veri yok'}</small></article></section><div class="section-head"><div><span>SON 7 GÜN</span><h2>Çalışma ritmin</h2></div></div><section class="weekly-chart">${lastSeven.map(date=>{const value=progress.dailyStats[date]?.answered||0;const label=new Date(`${date}T12:00:00`).toLocaleDateString('tr-TR',{weekday:'short'}).replace('.','');return `<div><b>${value||''}</b><span><i style="height:${Math.max(value?8:2,(value/maxDaily)*100)}%"></i></span><small>${label}</small></div>`}).join('')}</section><p class="statistics-note">Buradaki başarıdan daha önemli ölçü, <b>bağımsız hatırlama oranıdır.</b> Şıklara ihtiyaç azaldıkça bilgi gerçekten yerleşiyor demektir.</p>`,{active:'more'});
