    const upcoming=activeReviews.filter(([id])=>!dueSet.has(id)).sort((a,b)=>String(a[1].nextDueAt||a[1].nextDue).localeCompare(String(b[1].nextDueAt||b[1].nextDue)));
    const formatDue=review=>new Date(review.nextDueAt||reviewTimeForDate(review.nextDue)).toLocaleString('tr-TR',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'});
    const next=upcoming[0]?.[1], cards=upcoming.slice(0,8).map(([id,review])=>{const question=allQuestions.find(item=>item.id===id);return question?`<article class="notification-review"><span>${review.stage+1}</span><div><strong>${escape(question.question)}</strong><small>${formatDue(review)} · ${review.stage+1}. tekrar</small></div></article>`:''}).join('');
