    const verificationPanel=progress.verificationQuestions.length?`<section class="verification-hero"><div class="eyebrow">DOĞRULAMA HAVUZU</div><h1>${verificationDue.length?`${verificationDue.length} bilgi hazır`:`${verificationUpcoming.length} bilgi 3 günlük beklemede`}</h1><p>${verificationDue.length?'Bu bilgileri şıksız çağırarak gerçekten öğrenip öğrenmediğini kontrol et.':`İlk doğrulama ${new Date(progress.verificationSchedule[verificationUpcoming[0]]?.dueAt).toLocaleString('tr-TR',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})} tarihinde açılacak.`}</p><button class="btn ${verificationDue.length?'btn-primary':'btn-secondary'} btn-block" data-route="verification">HAVUZU AÇ</button></section>`:'';
